module Top;
  int seed;
  int unsigned a, b, c, d, e, ignored;
  initial begin
    seed=0; a=$urandom(seed); b=$urandom;
    seed=0; c=$urandom(seed); d=$urandom;
    $display("zero_seed_repeat=%0d", a==c && b==d);
    seed=123; a=$urandom(seed); b=$urandom; c=$urandom;
    seed=123; ignored=$urandom(seed); d=$urandom; e=$urandom;
    $display("nonzero_seed_repeat=%0d", b==d && c==e);
    $finish;
  end
endmodule

