module Top;
      function automatic logic check_seed(input logic [7:0] raw);
        logic signed [7:0] narrow;
        logic [7:0] unsigned_narrow;
        int extended, unsigned_extended;
        int unsigned a, b, c, d;
        narrow = raw; unsigned_narrow = raw;
        extended = int'(narrow); unsigned_extended = int'(unsigned_narrow);
        a = $urandom(narrow); b = $urandom(extended);
        c = $urandom(unsigned_narrow); d = $urandom(unsigned_extended);
        return a == b && c == d;
      endfunction
      initial begin
        for (int i = 1; i < 256; i++) begin
          if (!check_seed(i)) $fatal(1, "seed extension mismatch at %0d", i);
        end
        $display("nonzero_seed_extension=1");
        $finish;
      end
endmodule
